const ADMIN_SESSION_MS=10*60*1000;
const DAYS=[{v:1,l:"月"},{v:2,l:"火"},{v:3,l:"水"},{v:4,l:"木"},{v:5,l:"金"},{v:6,l:"土"},{v:0,l:"日"}];
const TODAY_FILTER={status:"all",vendor:"all",query:""};
const PRESET_FILTER={query:"",sort:"recent"};
