  const statusCounts=[];
  for(const a of pkg.links||[]){const m=String(a?.text||"").match(/^(.+?)\s*(\d+)件$/);if(/^status\d+$/.test(String(a?.id||""))&&m)statusCounts.push({id:a.id,label:tradeNorm(m[1]),count:+m[2]})}
