function catalogReadQty(productId){
  const p=P(productId),el=$(`[data-catalog-qty="${CSS.escape(productId)}"]`);
  if(!p||!el)throw Error("商品の数量欄が見つかりません");
  const raw=el.value.trim();
  if(!raw)throw Error(`${p.name||p.code} の数量を入力してください`);
  const q=Number(raw);
  if(!Number.isFinite(q)||q<=0)throw Error(`${p.name||p.code} の数量は0より大きい数字にしてください`);
  if(p.allowDecimalQty!==true&&!Number.isInteger(q))throw Error(`${p.name||p.code} は整数数量で入力してください`);
  return q;
}
function catalogAddProducts(ids){
  const unique=[...new Set(ids||[])].filter(Boolean);
  if(!unique.length){alert("追加する商品を選んでください");return}
  let pr=null,created=false;
  if(CATALOG_PRESET_ID==="__new__"){
    const name=$("#catalogNewPresetName")?.value.trim();
    if(!name){alert("新しいプリセット名を入力してください");$("#catalogNewPresetName")?.focus();return}
    if((S.presets||[]).some(x=>x.name===name)){alert("同じ名前のプリセットがあります。上の追加先から既存プリセットを選んでください。");return}
    pr={id:uid(),name,items:[]};created=true;
  }else{
    pr=S.presets.find(x=>x.id===CATALOG_PRESET_ID);
    if(!pr){alert("追加先プリセットが見つかりません");return}
  }
  const existing=new Set((pr.items||[]).map(i=>i.productId)),add=[];
  try{
    for(const id of unique){
      if(existing.has(id))continue;
      const p=P(id);
      if(!p||p.masterOrphan)continue;
      add.push({productId:id,qty:catalogReadQty(id)});
    }
  }catch(e){alert(e.message);return}
  if(!add.length){alert("新しく追加できる商品がありません");return}
  checkpoint("発注先商品からプリセット追加前");
  if(created)S.presets.push(pr);
  pr.items.push(...add);
  CATALOG_PRESET_ID=pr.id;
  CATALOG_SELECTION.clear();
  save("発注先商品からプリセットへ追加");
  alert(`${add.length}商品を「${pr.name}」へ追加しました。`);
}

function catalogStatusInfo(p){
  if(p.catalogStatus==="listed")return {label:"掲載確認済み",cls:"ok"};
  if(p.catalogStatus==="not-listed-candidate")return {label:"掲載なし候補",cls:"warn"};
  if(p.imageSource&&!p.domSource)return {label:"画像仮登録",cls:"warn"};
  if(p.domSource)return {label:"DOM登録済み",cls:"neutral"};
  return {label:"掲載未確認",cls:"neutral"};
}
