  $("#catalogAll")?.addEventListener("click",()=>{CATALOG_FILTER.mine=false;render()});
  $("#catalogMine")?.addEventListener("click",()=>{CATALOG_FILTER.mine=true;render()});
  $$("[data-catalog-check]").forEach(c=>c.onchange=()=>{if(c.checked)CATALOG_SELECTION.add(c.dataset.catalogCheck);else CATALOG_SELECTION.delete(c.dataset.catalogCheck);const n=$("#catalogSelectedCount");if(n)n.textContent=CATALOG_SELECTION.size;const b=$("#catalogAddSelected");if(b)b.disabled=!CATALOG_SELECTION.size});
  $$("[data-catalog-one]").forEach(b=>b.onclick=()=>catalogAddProducts([b.dataset.catalogOne]));
  $("#catalogAddSelected")?.addEventListener("click",()=>catalogAddProducts([...CATALOG_SELECTION]));
